import { ref, computed } from 'vue'
import {
  calculateLevel,
  calculateCurrentXP,
  calculateNeededXPForNextLevel,
} from '~/utils/levelCalculator'

export const useUserStore = defineStore(
  'user',
  () => {
    const totalXP = ref<number>(0)
    const coins = ref<number>(100)
    const leaguePoints = ref<number>(0)

    const profile = ref({
      name: '',
      bio: '',
      email: '',
      avatar: '',
    })

    const level = computed(() => calculateLevel(totalXP.value))
    const currentXP = computed(() =>
      calculateCurrentXP(totalXP.value, level.value)
    )
    const neededXPForNextLevel = computed(() =>
      calculateNeededXPForNextLevel(level.value)
    )
    const levelProgressPercent = computed(() => {
      if (neededXPForNextLevel.value === 0) return 100
      return (currentXP.value / neededXPForNextLevel.value) * 100
    })

    const league = computed(() => {
      if (leaguePoints.value < 1000) return 'Бронза'
      if (leaguePoints.value < 3000) return 'Серебро'
      if (leaguePoints.value < 6000) return 'Золото'
      return 'Платина'
    })

    function addXP(amount: number) {
      totalXP.value += amount
      leaguePoints.value += amount * 0.5
    }

    function addCoins(amount: number) {
      coins.value += amount
    }

    function reduceLeaguePoints(amount: number) {
      leaguePoints.value = Math.max(0, leaguePoints.value - amount)
    }

    function updateProfile(newProfile: Partial<typeof profile.value>) {
      profile.value = { ...profile.value, ...newProfile }
    }

    return {
      totalXP,
      coins,
      leaguePoints,
      profile,
      level,
      currentXP,
      neededXPForNextLevel,
      levelProgressPercent,
      league,
      addXP,
      addCoins,
      reduceLeaguePoints,
      updateProfile,
    }
  },
  {
    persist: import.meta.client
      ? { key: 'carbon-user', storage: localStorage }
      : undefined,
  }
)
import { defineStore } from 'pinia'
import { ref } from 'vue'
import type { Branch, BranchId, Milestone } from '~/types/branch.types'
import type { Edge } from '@vue-flow/core'
import { v4 as uuidv4 } from 'uuid'

export const useBranchesStore = defineStore(
  'branches',
  () => {
    const branches = ref<Branch[]>([
      {
        id: 'FIN',
        displayName: 'Финансы',
        icon: 'trending-up',
        description: '',
        taskIds: [],
        milestones: [
          {
            id: uuidv4(),
            name: 'Основы финансов',
            icon: 'trending-up',
            description: '',
            requiredXP: 500,
            currentXP: 0,
            status: 'pending',
            taskIds: [],
            position: { x: 200, y: 200 },
          },
        ],
        order: 0,
      },
      {
        id: 'BODY',
        displayName: 'Тело',
        icon: 'dumbbell',
        description: '',
        taskIds: [],
        milestones: [
          {
            id: uuidv4(),
            name: 'Регулярные тренировки',
            icon: 'dumbbell',
            description: '',
            requiredXP: 300,
            currentXP: 0,
            status: 'pending',
            taskIds: [],
            position: { x: 500, y: 200 },
          },
        ],
        order: 1,
      },
      {
        id: 'MIND',
        displayName: 'Интеллект',
        icon: 'brain',
        description: '',
        taskIds: [],
        milestones: [
          {
            id: uuidv4(),
            name: 'Ежедневное чтение',
            icon: 'brain',
            description: '',
            requiredXP: 400,
            currentXP: 0,
            status: 'pending',
            taskIds: [],
            position: { x: 800, y: 200 },
          },
        ],
        order: 2,
      },
      {
        id: 'LDR',
        displayName: 'Лидерство',
        icon: 'users',
        description: '',
        taskIds: [],
        milestones: [
          {
            id: uuidv4(),
            name: 'Первая публичная речь',
            icon: 'users',
            description: '',
            requiredXP: 200,
            currentXP: 0,
            status: 'pending',
            taskIds: [],
            position: { x: 1100, y: 200 },
          },
        ],
        order: 3,
      },
    ])

    const edges = ref<Edge[]>([])

    function cleanupEdges() {
      const existingNodeIds = new Set(
        branches.value.flatMap((b) => b.milestones.map((m) => m.id))
      )
      edges.value = edges.value.filter(
        (e) => existingNodeIds.has(e.source) && existingNodeIds.has(e.target)
      )
    }

    function addXPToBranch(branchId: BranchId, xp: number) {
      const branch = branches.value.find((b) => b.id === branchId)
      if (!branch) return

      const activeMilestone = branch.milestones.find(
        (m) => m.status === 'active'
      )
      if (activeMilestone) {
        activeMilestone.currentXP += xp
        updateMilestoneStatus(activeMilestone)
      } else {
        const pendingMilestone = branch.milestones.find(
          (m) => m.status === 'pending'
        )
        if (pendingMilestone) {
          pendingMilestone.currentXP += xp
          pendingMilestone.status = 'active'
          updateMilestoneStatus(pendingMilestone)
        }
      }
    }

    function updateMilestoneStatus(milestone: Milestone) {
      if (milestone.currentXP >= milestone.requiredXP) {
        milestone.status = 'completed'
        const branch = branches.value.find((b) =>
          b.milestones.some((m) => m.id === milestone.id)
        )
        if (branch) {
          const nextXP = Math.floor(milestone.requiredXP * 1.5)
          const newMilestone: Milestone = {
            id: uuidv4(),
            name: `Новый этап`,
            icon: branch.icon,
            description: '',
            requiredXP: nextXP,
            currentXP: 0,
            status: 'pending',
            taskIds: [],
            position: {
              x: milestone.position.x + 250,
              y: milestone.position.y,
            },
          }
          branch.milestones.push(newMilestone)
          edges.value.push({
            id: uuidv4(),
            source: milestone.id,
            target: newMilestone.id,
            type: 'smoothstep',
            animated: false,
            style: { stroke: 'var(--accent)', strokeWidth: 1 },
          })
        }
      } else {
        milestone.status = 'active'
      }
    }

    function addBranch(
      displayName: string,
      icon: string,
      description: string = '',
      taskIds: string[] = []
    ) {
      let x = 200
      let y = 200
      if (branches.value.length > 0) {
        const lastBranch = branches.value[branches.value.length - 1]
        const lastMilestone = lastBranch.milestones[0]
        if (lastMilestone) {
          x = lastMilestone.position.x + 300
          y = lastMilestone.position.y
        }
      }

      const newBranch: Branch = {
        id: uuidv4(),
        displayName,
        icon,
        description,
        taskIds,
        milestones: [
          {
            id: uuidv4(),
            name: displayName,
            icon,
            description,
            requiredXP: 500,
            currentXP: 0,
            status: 'pending',
            taskIds: taskIds,
            position: { x, y },
          },
        ],
        order: branches.value.length,
      }
      branches.value.push(newBranch)
    }

    function deleteBranch(branchId: string) {
      const index = branches.value.findIndex((b) => b.id === branchId)
      if (index !== -1) {
        const milestoneIds = branches.value[index].milestones.map((m) => m.id)
        edges.value = edges.value.filter(
          (e) =>
            !milestoneIds.includes(e.source) && !milestoneIds.includes(e.target)
        )
        branches.value.splice(index, 1)
      }
    }

    function addMilestone(
      branchId: BranchId,
      name: string,
      description: string = '',
      position?: { x: number; y: number }
    ) {
      const branch = branches.value.find((b) => b.id === branchId)
      if (!branch) return
      const last = branch.milestones[branch.milestones.length - 1]
      const newMilestone: Milestone = {
        id: uuidv4(),
        name,
        icon: branch.icon,
        description,
        requiredXP: last ? Math.floor(last.requiredXP * 1.5) : 500,
        currentXP: 0,
        status: 'pending',
        taskIds: [],
        position: position || {
          x: (last?.position.x || 200) + 250,
          y: last?.position.y || 200,
        },
      }
      branch.milestones.push(newMilestone)
      if (last) {
        edges.value.push({
          id: uuidv4(),
          source: last.id,
          target: newMilestone.id,
          type: 'smoothstep',
          animated: false,
          style: { stroke: 'var(--accent)', strokeWidth: 1 },
        })
      }
    }

    function updateMilestone(milestoneId: string, updates: Partial<Milestone>) {
      for (const branch of branches.value) {
        const milestone = branch.milestones.find((m) => m.id === milestoneId)
        if (milestone) {
          if (updates.name !== undefined) milestone.name = updates.name
          if (updates.description !== undefined)
            milestone.description = updates.description
          if (updates.icon !== undefined) milestone.icon = updates.icon
          if (updates.taskIds !== undefined) milestone.taskIds = updates.taskIds
          if (updates.requiredXP !== undefined)
            milestone.requiredXP = updates.requiredXP
          if (updates.currentXP !== undefined)
            milestone.currentXP = updates.currentXP
          if (updates.status !== undefined) milestone.status = updates.status
          if (updates.position !== undefined)
            milestone.position = updates.position
          break
        }
      }
    }

    function deleteMilestone(milestoneId: string) {
      for (const branch of branches.value) {
        const index = branch.milestones.findIndex((m) => m.id === milestoneId)
        if (index !== -1) {
          branch.milestones.splice(index, 1)
          edges.value = edges.value.filter(
            (e) => e.source !== milestoneId && e.target !== milestoneId
          )
          break
        }
      }
    }

    function addEdge(edge: Edge) {
      edges.value.push(edge)
    }

    function removeEdge(edgeId: string) {
      edges.value = edges.value.filter((e) => e.id !== edgeId)
    }

    function updateEdge(updatedEdge: Edge) {
      const index = edges.value.findIndex((e) => e.id === updatedEdge.id)
      if (index !== -1) {
        edges.value[index] = updatedEdge
      }
    }

    function updateBranch(branchId: string, updates: Partial<Branch>) {
      const branch = branches.value.find((b) => b.id === branchId)
      if (branch) {
        if (updates.displayName !== undefined)
          branch.displayName = updates.displayName
        if (updates.icon !== undefined) branch.icon = updates.icon
        if (updates.description !== undefined)
          branch.description = updates.description
        if (updates.taskIds !== undefined) branch.taskIds = updates.taskIds

        const firstMilestone = branch.milestones[0]
        if (firstMilestone) {
          if (updates.displayName) firstMilestone.name = updates.displayName
          if (updates.icon) firstMilestone.icon = updates.icon
          if (updates.description)
            firstMilestone.description = updates.description
          if (updates.taskIds) firstMilestone.taskIds = updates.taskIds
        }
      }
    }

    if (import.meta.client) {
      Promise.resolve().then(() => cleanupEdges())
    }

    return {
      branches,
      edges,
      addXPToBranch,
      addBranch,
      deleteBranch,
      addMilestone,
      updateMilestone,
      deleteMilestone,
      addEdge,
      removeEdge,
      updateEdge,
      updateBranch,
    }
  },
  {
    persist: import.meta.client
      ? { key: 'carbon-branches', storage: localStorage }
      : undefined,
  }
)
import { defineStore } from 'pinia'
import { ref, watch } from 'vue'
import type { Tag } from '~/types/tag.types'
import { v4 as uuidv4 } from 'uuid'

type InternalTag = Tag & { isSystem?: boolean }

const DEFAULT_TAGS: (Omit<Tag, 'id'> & { isSystem: boolean })[] = [
  { name: '#финансы', branchId: 'FIN', order: 1, isSystem: true },
  { name: '#тело', branchId: 'BODY', order: 2, isSystem: true },
  { name: '#интеллект', branchId: 'MIND', order: 3, isSystem: true },
  { name: '#лидерство', branchId: 'LDR', order: 4, isSystem: true },
  { name: '#работа', branchId: 'FIN', order: 5, isSystem: true },
  { name: '#спорт', branchId: 'BODY', order: 6, isSystem: true },
  { name: '#учёба', branchId: 'MIND', order: 7, isSystem: true },
  { name: '#нетворкинг', branchId: 'LDR', order: 8, isSystem: true },
]

export const useTagsStore = defineStore(
  'tags',
  () => {
    const tags = ref<InternalTag[]>([])

    async function initTagsAfterHydration() {
      const store = useTagsStore()
      if (store.$persistedState) {
        await store.$persistedState.isReady
      }
      ensureSystemTags()
    }

    function ensureSystemTags() {
      const systemNames = DEFAULT_TAGS.map((t) => t.name)
      const existingNames = tags.value.map((t) => t.name)
      const missing = systemNames.filter(
        (name) => !existingNames.includes(name)
      )

      if (missing.length > 0) {
        const restored = DEFAULT_TAGS.filter((t) =>
          missing.includes(t.name)
        ).map((t) => ({
          ...t,
          id: uuidv4(),
        }))
        tags.value.push(...restored)
      }
    }

    function getTagById(id: string): InternalTag | undefined {
      return tags.value.find((t) => t.id === id)
    }

    function getTagsByIds(ids: string[]): InternalTag[] {
      return tags.value.filter((t) => ids.includes(t.id))
    }

    function addTag(tagData: Omit<Tag, 'id'>) {
      const newTag: InternalTag = { ...tagData, id: uuidv4(), isSystem: false }
      tags.value.push(newTag)
      return newTag
    }

    function deleteTag(id: string): boolean {
      const index = tags.value.findIndex((t) => t.id === id)
      if (index === -1) return false
      if (tags.value[index].isSystem) return false
      tags.value.splice(index, 1)
      return true
    }

    watch(
      tags,
      () => {
        ensureSystemTags()
      },
      { deep: true }
    )

    return {
      tags,
      initTagsAfterHydration,
      getTagById,
      getTagsByIds,
      addTag,
      deleteTag,
    }
  },
  {
    persist: import.meta.client
      ? { key: 'carbon-tags', storage: localStorage }
      : undefined,
  }
)
import { defineStore } from 'pinia'
import { ref } from 'vue'
import type { Reward } from '~/types/reward.types'
import { v4 as uuidv4 } from 'uuid'
import { useUserStore } from './user.store'

export const useRewardsStore = defineStore(
  'rewards',
  () => {
    const rewards = ref<Reward[]>([])

    async function initDemoRewardsAfterHydration() {
      const DEMO_KEY = 'carbon-rewards-demo-initialized'
      const store = useRewardsStore()
      if (store.$persistedState) await store.$persistedState.isReady
      if (rewards.value.length === 0 && !localStorage.getItem(DEMO_KEY)) {
        rewards.value = [
          {
            id: uuidv4(),
            title: 'Новая одежда',
            description: 'Обнови гардероб',
            price: 3000,
            purchased: false,
            completed: false,
            effect: { leaguePoints: 200, xp: 500 },
          },
          {
            id: uuidv4(),
            title: 'Книга по инвестициям',
            price: 1500,
            purchased: false,
            completed: false,
            effect: { xp: 300, coins: 200 },
          },
        ]
        localStorage.setItem(DEMO_KEY, 'true')
      }
    }

    function purchaseReward(id: string) {
      const userStore = useUserStore()
      const reward = rewards.value.find((r) => r.id === id)
      if (!reward || reward.purchased) return
      if (userStore.coins < reward.price) return

      userStore.addCoins(-reward.price)
      reward.purchased = true
      reward.purchasedAt = Date.now()
    }

    function confirmPurchase(rewardId: string) {
      const userStore = useUserStore()
      const reward = rewards.value.find((r) => r.id === rewardId)
      if (!reward || reward.completed) return

      reward.completed = true
      reward.completedAt = Date.now()

      if (reward.effect) {
        if (reward.effect.xp) userStore.addXP(reward.effect.xp)
        if (reward.effect.coins) userStore.addCoins(reward.effect.coins)
        if (reward.effect.leaguePoints)
          userStore.leaguePoints += reward.effect.leaguePoints
      }
    }

    if (import.meta.client) {
      initDemoRewardsAfterHydration()
    }

    return { rewards, purchaseReward, confirmPurchase }
  },
  {
    persist: import.meta.client
      ? { key: 'carbon-rewards', storage: localStorage }
      : undefined,
  }
)
import { defineStore } from 'pinia'
import { ref } from 'vue'
import type { Task, TaskType } from '~/types/task.types'
import { v4 as uuidv4 } from 'uuid'
import { useUserStore } from './user.store'
import { useBranchesStore } from './branches.store'
import { useTagsStore } from './tags.store'
import { useRewardsStore } from './rewards.store'

export const useTasksStore = defineStore(
  'tasks',
  () => {
    const tasks = ref<Task[]>([])

    function getTodayDateString(): string {
      return new Date().toISOString().split('T')[0]
    }

    function addTask(
      taskData: Omit<Task, 'id' | 'createdAt' | 'done'> & { id?: string }
    ): Task | null {
      if (taskData.type.startsWith('TASK_')) {
        const activeCount = tasks.value.filter(
          (t) => t.type === taskData.type && !t.done
        ).length
        if (activeCount >= 3) return null
      }
      const newTask: Task = {
        id: taskData.id || uuidv4(),
        ...taskData,
        done: false,
        createdAt: taskData.createdAt || Date.now(),
      }
      tasks.value.push(newTask)
      return newTask
    }

    function completeTask(id: string) {
      const task = tasks.value.find((t) => t.id === id)
      if (!task) return
      const userStore = useUserStore()
      const branchesStore = useBranchesStore()
      const tagsStore = useTagsStore()
      const rewardsStore = useRewardsStore()

      if (task.type === 'HABIT') {
        task.lastCompletedAt = Date.now()
        const tags = tagsStore.getTagsByIds(task.tagIds)
        const xpPerTag = 50
        tags.forEach((tag) => {
          branchesStore.addXPToBranch(tag.branchId, xpPerTag)
        })
        userStore.addXP(xpPerTag * tags.length)
        return
      }

      if (!task.done) {
        task.done = true
        task.completedAt = Date.now()
        const tags = tagsStore.getTagsByIds(task.tagIds)
        const baseXP = task.type === 'PURCHASE' ? 500 : 100
        tags.forEach((tag) => {
          branchesStore.addXPToBranch(tag.branchId, baseXP)
        })
        userStore.addXP(baseXP * tags.length)

        if (task.type === 'PURCHASE' && task.purchaseRewardId) {
          rewardsStore.confirmPurchase(task.purchaseRewardId)
        }
      }
    }

    function deleteTask(id: string) {
      const index = tasks.value.findIndex((t) => t.id === id)
